'use client';

import React, { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { motion } from 'framer-motion';
import { BarChart3, Lightbulb, Loader2, Play } from 'lucide-react';
import { fetchCandidateInterviews, fetchSessionScorecard } from '@/lib/api';

const BAR_COLORS = ['bg-cyan-400', 'bg-emerald-400', 'bg-indigo-400', 'bg-sky-400', 'bg-amber-400'];

interface AggregatedCompetency {
  name: string;
  score: number;
  sessions: number;
}

/**
 * Competency scores are real: they live on `Scorecard.competencies` and are
 * generated by the LLM on a 0-100 scale. This card averages them across every
 * completed session the candidate owns. The previous version shipped four
 * hardcoded pillars (88 / 92 / 84 / 90) that no endpoint ever produced.
 */
export const CompetencyCard: React.FC = () => {
  const [competencies, setCompetencies] = useState<AggregatedCompetency[] | null>(null);
  const [sessionCount, setSessionCount] = useState(0);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      const sessions = await fetchCandidateInterviews();
      if (cancelled) return;

      const sessionList: any[] = Array.isArray(sessions) ? sessions : Array.isArray((sessions as any)?.completed) ? (sessions as any).completed : [];
      const completed = sessionList.filter((session: any) => session.status === 'completed' || session.completedAt);
      setSessionCount(completed.length);

      if (completed.length === 0) {
        setCompetencies([]);
        return;
      }

      const scorecards = await Promise.all(completed.slice(0, 5).map((s: any) => fetchSessionScorecard(s.id)));
      if (cancelled) return;

      const totals = new Map<string, { sum: number; count: number }>();
      for (const card of scorecards) {
        if (!card) continue;
        for (const comp of card.competencies) {
          if (typeof comp.score !== 'number') continue;
          const key = comp.competency.trim();
          if (!key) continue;
          const entry = totals.get(key) ?? { sum: 0, count: 0 };
          entry.sum += comp.score;
          entry.count += 1;
          totals.set(key, entry);
        }
      }

      const aggregated = [...totals.entries()]
        .map(([name, { sum, count }]) => ({
          name,
          score: Math.round((sum / count) * 10) / 10,
          sessions: count
        }))
        .sort((a, b) => b.score - a.score)
        .slice(0, 5);

      setCompetencies(aggregated);
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  const top = useMemo(() => competencies?.[0], [competencies]);
  const hasData = (competencies?.length ?? 0) > 0;

  return (
    <motion.div
      initial={{ opacity: 1, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.2 }}
      className="p-6 rounded-2xl bg-surface border border-line shadow-2xl backdrop-blur-md flex flex-col justify-between space-y-6"
    >
      <div>
        <div className="flex items-center space-x-2 mb-1">
          <BarChart3 className="w-5 h-5 text-accent-cyan" />
          <h3 className="text-lg font-bold text-ink tracking-tight">Verified Technical Competency</h3>
        </div>
        <p className="text-xs text-ink-muted">
          {sessionCount > 0
            ? `Averaged across ${sessionCount} completed AI video interview${sessionCount === 1 ? '' : 's'}.`
            : 'Generated from your completed AI video interviews.'}
        </p>
      </div>

      <div className="space-y-4">
        {competencies === null ? (
          <div className="flex items-center gap-2 py-6 text-sm text-ink-muted">
            <Loader2 className="w-4 h-4 animate-spin text-accent-cyan" />
            Loading competency scores…
          </div>
        ) : !hasData ? (
          <div className="py-6 text-center space-y-3">
            <div>
              <p className="text-sm text-ink">No competency scores yet</p>
              <p className="text-xs text-ink-muted mt-1">
                Scores appear here once you complete an interview session.
              </p>
            </div>
            <Link
              href="/candidate/practice"
              className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold text-white bg-gradient-to-r from-cyan-500 to-indigo-600 hover:from-cyan-400 hover:to-indigo-500 transition-all cursor-pointer"
            >
              <Play className="w-3.5 h-3.5 fill-current" />
              Start your first practice interview
            </Link>
          </div>
        ) : (
          competencies!.map((item, idx) => (
            <div key={item.name} className="space-y-1.5">
              <div className="flex items-center justify-between text-xs gap-3">
                <span className="font-semibold text-ink truncate">{item.name}</span>
                <span className="font-mono font-bold text-ink shrink-0">{item.score} / 100</span>
              </div>

              <div className="w-full h-2 rounded-full bg-inset overflow-hidden">
                <motion.div
                  initial={{ width: 0 }}
                  animate={{ width: `${Math.max(0, Math.min(100, item.score))}%` }}
                  transition={{ duration: 0.8, delay: 0.3 }}
                  className={`h-full rounded-full ${BAR_COLORS[idx % BAR_COLORS.length]}`}
                />
              </div>
            </div>
          ))
        )}
      </div>

      <div className="p-3.5 rounded-xl bg-inset flex items-start space-x-3">
        <Lightbulb className="w-4 h-4 text-accent-amber shrink-0 mt-0.5" />
        <p className="text-xs text-ink leading-normal">
          {top ? (
            <>
              <span className="font-semibold text-accent-amber">Strongest area:</span> {top.name} — averaged{' '}
              {top.score} / 100 across {top.sessions} scored session{top.sessions === 1 ? '' : 's'}.
            </>
          ) : (
            <span className="text-ink-muted">
              Complete an interview and your strongest competency will be highlighted here.
            </span>
          )}
        </p>
      </div>
    </motion.div>
  );
};